package de.bsnsoft.esj.generator;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

/**
 * The text mechanics the emitters share: the header every generated file carries, the
 * escaping a Javadoc comment needs, and the two places where a line is broken so that the
 * output stays readable and identical on every machine.
 */
final class JavaText {

    private static final int WIDTH = 100;

    /** The first line of every generated file, which also marks a file as generated. */
    static final String HEADER_MARKER = "// Generated by esj-generator from EN16931 registry";

    /** The first line of a file generated from code list snapshots rather than from the registry. */
    static final String CODE_LIST_HEADER_MARKER =
            "// Generated by esj-generator from the code list snapshots";

    private JavaText() {
    }

    /**
     * Returns the three-line header of a generated file.
     *
     * @param edition the edition of the model the registry describes
     * @param version the version of the registry file
     * @return the header, ending in a line break
     */
    static String header(String edition, String version) {
        return HEADER_MARKER + "\n"
                + "// " + edition + ", registry version " + version + ".\n"
                + "// Do not edit.\n";
    }

    /**
     * Returns the three-line header of a file generated from code list snapshots, which
     * also marks such a file as generated.
     *
     * @param packId      the rule pack the snapshots belong to
     * @param packVersion the version of that pack
     * @param lists       the snapshots, each as {@code <list> of <day>}
     * @return the header, ending in a line break
     */
    static String codeListHeader(String packId, String packVersion, List<String> lists) {
        return CODE_LIST_HEADER_MARKER + "\n"
                + "// of the rule pack " + packId + " " + packVersion + ": "
                + String.join(", ", lists) + ".\n"
                + "// Do not edit.\n";
    }

    /**
     * Escapes text for a Javadoc comment.
     *
     * @param text the text as the registry writes it
     * @return the text with the three characters an HTML fragment reserves replaced, and
     *         with no sequence that would end the comment
     */
    static String escape(String text) {
        return Objects.requireNonNull(text, "text")
                .replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("*/", "*&#47;");
    }

    /**
     * Wraps a paragraph of a Javadoc comment.
     *
     * @param indent the indentation of the comment, in spaces
     * @param first  the text that opens the first line, for example {@code  * } or
     *               {@code  * @return }
     * @param text   the paragraph, already escaped
     * @return the lines of the paragraph, each ending in a line break
     */
    static String wrap(String indent, String first, String text) {
        String continuation = first.startsWith(" * @") ? indent + " *     " : indent + " * ";
        StringBuilder out = new StringBuilder();
        StringBuilder line = new StringBuilder(indent).append(first);
        int start = line.length();
        boolean empty = true;
        for (String word : text.split(" ")) {
            if (word.isEmpty()) {
                continue;
            }
            if (!empty && line.length() + 1 + word.length() > WIDTH) {
                out.append(line).append('\n');
                line = new StringBuilder(continuation);
                empty = true;
            }
            if (!empty) {
                line.append(' ');
            }
            line.append(word);
            empty = false;
        }
        if (line.length() > start || !empty) {
            out.append(line).append('\n');
        }
        return out.toString();
    }

    /**
     * Writes a statement, breaking the argument list when the statement does not fit on
     * one line.
     *
     * @param indent    the indentation of the statement, in spaces
     * @param head      the text up to and including the opening parenthesis
     * @param arguments the arguments, without their separating commas
     * @param tail      the text after the closing parenthesis, for example a semicolon
     * @return the statement, ending in a line break
     */
    static String call(String indent, String head, List<String> arguments, String tail) {
        StringBuilder oneLine = new StringBuilder(indent).append(head);
        for (int i = 0; i < arguments.size(); i++) {
            oneLine.append(i == 0 ? "" : ", ").append(arguments.get(i));
        }
        oneLine.append(')').append(tail);
        if (oneLine.length() <= WIDTH) {
            return oneLine + "\n";
        }
        List<String> lines = new ArrayList<>();
        String continuation = indent + "        ";
        StringBuilder line = new StringBuilder(indent).append(head);
        for (int i = 0; i < arguments.size(); i++) {
            String argument = arguments.get(i) + (i == arguments.size() - 1 ? "" : ",");
            if (line.length() + argument.length() > WIDTH) {
                lines.add(line.toString());
                line = new StringBuilder(continuation);
            } else if (i > 0) {
                line.append(' ');
            }
            line.append(argument);
        }
        lines.add(line + ")" + tail);
        return String.join("\n", lines) + "\n";
    }
}
